package glitch

import data.glitch_lib

password_pattern = "(?i)(password|passwd|pwd|passphrase|secret|credentials|auth_token|api_key|key)"

empty_value(v) {
    v.ir_type == "String"
    v.value == ""
} else {
    v.ir_type == "Null"
} else {
    v.ir_type == "Undef"
}

connection_string_patterns = {
    "(?i).*;pwd=;.*",
    "(?i).*:password@.*",
    "(?i).*\\?password=.*",
    "(?i).*user: ?@host.*"
}

connection_string_pattern_matches(str) {
    pattern := connection_string_patterns[_]
    regex.match(pattern, str)
}

contains_sensitive_word(name) {
    regex.match(password_pattern, name)
}

find_variable_in_scope(var_name, node) = var {
    vars := glitch_lib.all_variables(node)
    var := vars[_]
    var.name == var_name
}

check_var_ref_empty_in_scope(var_ref, node) {
    var_ref.ir_type == "VariableReference"
    var_name := var_ref.value
    var := find_variable_in_scope(var_name, node)
    empty_value(var.value)
}

contains_exclusion_term(name) {
    regex.match("(?i).*(cache|proxy|ssl|clientkey|certificate|keyfile|cert).*", name)
}

find_variable_in_project(var_name) = var {
    some ub
    glitch_lib._gather_parent_unit_blocks[ub]
    vars := glitch_lib.all_variables(ub)
    var := vars[_]
    var.name == var_name
}

check_var_ref_empty_in_project(var_ref) {
    var_ref.ir_type == "VariableReference"
    var_name := var_ref.value
    var := find_variable_in_project(var_name)
    empty_value(var.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    variables := glitch_lib.all_variables(parent)
    var := variables[_]
    contains_sensitive_word(var.name)
    empty_value(var.value)
    not contains_exclusion_term(var.name)

    result := {
